#!/usr/bin/env python3
"""Validate normalized-depth candidate abundance through wrapper outputs.

This closes the fixed-call diagnostic loop for the selected cross-panel
candidate rule as far as current cached inputs allow:

* Toy Mouse and CAMI3 use the emitted-profile candidate-rescue switch.
* HMP uses the integrated accession-level candidate-surface replay generated by
  validate_integrated_candidate_surface_hmp_abundance_policy.py.

All profiles are scored with the same GTDB truth/scorer helpers as the current
cross-panel abundance sweep, then compared against the fixed-call
normalized_depth_alpha2 policy.
"""

from __future__ import annotations

import math
import subprocess
import time
from pathlib import Path

import pandas as pd

import audit_hmp_missed_truth_raw_tables as raw_audit
import score_adaptive_call_filter_wrapper_validation as adaptive
import validate_integrated_candidate_surface_hmp_abundance_policy as hmp_abundance


EXP = Path(__file__).resolve().parent
REPO = EXP.parents[2]
RESULTS = EXP / "results"
OUT_DIR = Path("/tmp/minco_cross_panel_candidate_abundance_wrapper_20260629")
HMP_APPLY = RESULTS / "candidate_surface_integrated_hmp_abundance_apply.tsv"
EXPECTED = RESULTS / "cross_panel_candidate_abundance_policy_scores.tsv"
METHOD = "wrapper_candidate_abundance_normalized_depth_alpha2"
ZERO_METHOD = "wrapper_candidate_abundance_zero_mass"
EXPECTED_METHOD = "normalized_depth_alpha2"
POLICY = "normalized-depth-alpha2"
RESCUE_SWITCH = "emitted-ani90-xny100-br01-af70"
MODEL_CACHE = Path("/tmp/minco_model_cache_bench_20260627/minco_profile_rf_hgb.train12.unfiltered.joblib")
TRAIN_FEATURES = Path("/mnt/new3T/minco_cami2_strain_20260621/external_test_train9_strain0_2")
TOY_TAXMAP = Path("/tmp/cami2_toymouse_current_default_20260626/gtdb_r232_species.taxmap.tsv")
GTDB_TAXMAP = Path("/tmp/cami2_marine_samples3_5_20260625/run/gtdb232_refseqvirus_species_taxmap.tsv")


TOY_TABLES = {
    5: {
        "unique": Path("/tmp/cami2_toymouse_current_default_20260626/run/sample5_default/minco.best_diff_unique.unfiltered.tsv"),
        "split": Path("/tmp/cami2_toymouse_current_default_20260626/run/sample5_default/minco.best_diff_split.exact.unfiltered.tsv"),
    },
    6: {
        "unique": Path("/tmp/cami2_toymouse_current_default_20260626/run/sample6_default/minco.best_diff_unique.unfiltered.tsv"),
        "split": Path("/tmp/cami2_toymouse_current_default_20260626/run/sample6_default/minco.best_diff_split.unfiltered.tsv"),
    },
    7: {
        "unique": Path("/tmp/cami2_toymouse_current_default_20260626/run/sample7_default/minco.best_diff_unique.unfiltered.tsv"),
        "split": Path("/tmp/cami2_toymouse_current_default_20260626/run/sample7_default/minco.best_diff_split.unfiltered.tsv"),
    },
}
CAMI3_TABLES = {
    sample: {
        "unique": Path(f"/tmp/cami3_toy_human_gut_20260626/run/sample{sample}_autoexact/minco.best_diff_unique.unfiltered.tsv"),
        "split": Path(f"/tmp/cami3_toy_human_gut_20260626/run/sample{sample}_autoexact/minco.best_diff_split.unfiltered.tsv"),
    }
    for sample in [0, 1, 2]
}


def finite(value: object, default: float = 0.0) -> float:
    try:
        out = float(value)
    except (TypeError, ValueError):
        return default
    return out if math.isfinite(out) else default


def bool_series(values: pd.Series) -> pd.Series:
    return values.astype(str).str.strip().str.lower().isin({"true", "1", "yes"})


def parse_time_log(path: Path) -> dict[str, object]:
    text = path.read_text() if path.exists() else ""
    out = {"wall_clock": "", "max_rss_kb": "", "exit_status": ""}
    for line in text.splitlines():
        if "Elapsed (wall clock) time" in line:
            out["wall_clock"] = line.rsplit("):", 1)[-1].strip()
        elif "Maximum resident set size" in line:
            out["max_rss_kb"] = line.rsplit(":", 1)[-1].strip()
        elif "Exit status" in line:
            out["exit_status"] = line.rsplit(":", 1)[-1].strip()
    return out


def run_emitted_wrapper(
    panel: str,
    sample: int,
    unique: Path,
    split: Path,
    taxmap: Path,
    out: Path,
) -> dict[str, object]:
    time_log = OUT_DIR / f"{panel}.sample{sample}.time.log"
    if out.exists():
        return {
            "panel": panel,
            "sample": sample,
            "command": "reuse existing emitted wrapper profile",
            "elapsed_s": "0.000",
            "time_log": str(time_log),
            "wall_clock": "",
            "max_rss_kb": "",
            "exit_status": "0",
            "status": "reused",
        }
    cmd = [
        "/usr/bin/time",
        "-v",
        "-o",
        str(time_log),
        "python3",
        "-B",
        "scripts/minco_profile_calibrated.py",
        "--unique-table",
        str(unique),
        "--split-table",
        str(split),
        "--taxmap",
        str(taxmap),
        "--train-features",
        str(TRAIN_FEATURES),
        "--train-pool",
        "train12",
        "--scope",
        "bacteria",
        "--strategy",
        "universal-auto-exact",
        "--candidate-rescue-switch",
        RESCUE_SWITCH,
        "--candidate-abundance-policy",
        POLICY,
        "--report-all",
        "-o",
        str(out),
    ]
    if MODEL_CACHE.exists():
        cmd[cmd.index("--train-pool"):cmd.index("--train-pool")] = ["--model-cache", str(MODEL_CACHE)]
    start = time.monotonic()
    subprocess.run(cmd, cwd=REPO, check=True)
    elapsed = time.monotonic() - start
    timing = parse_time_log(time_log)
    timing.update(
        {
            "panel": panel,
            "sample": sample,
            "command": " ".join(cmd),
            "elapsed_s": f"{elapsed:.3f}",
            "time_log": str(time_log),
            "status": "ran",
        }
    )
    return timing


def replay_emitted_profiles() -> tuple[dict[tuple[str, int], Path], pd.DataFrame, pd.DataFrame]:
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    paths: dict[tuple[str, int], Path] = {}
    timing_rows: list[dict[str, object]] = []
    missing_rows: list[dict[str, object]] = []
    for sample, info in TOY_TABLES.items():
        panel = "cami2_toy_mouse_gut"
        out = OUT_DIR / f"toymouse_sample{sample}.normalized_depth_alpha2.tsv"
        unique = info["unique"]
        split = info["split"]
        if not unique.exists() or not split.exists():
            missing_rows.append(
                {"panel": panel, "sample": sample, "unique": str(unique), "split": str(split)}
            )
            continue
        timing_rows.append(run_emitted_wrapper(panel, sample, unique, split, TOY_TAXMAP, out))
        paths[(panel, sample)] = out
    for sample, info in CAMI3_TABLES.items():
        panel = "cami3_toy_human_gut_gtdb_source_readmap"
        out = OUT_DIR / f"cami3_sample{sample}.normalized_depth_alpha2.tsv"
        unique = info["unique"]
        split = info["split"]
        if not unique.exists() or not split.exists():
            missing_rows.append(
                {"panel": panel, "sample": sample, "unique": str(unique), "split": str(split)}
            )
            continue
        timing_rows.append(run_emitted_wrapper(panel, sample, unique, split, GTDB_TAXMAP, out))
        paths[(panel, sample)] = out
    return paths, pd.DataFrame(timing_rows), pd.DataFrame(missing_rows)


def hmp_paths() -> tuple[dict[tuple[str, int], Path], pd.DataFrame]:
    if not HMP_APPLY.exists():
        raise SystemExit(
            f"missing HMP wrapper replay table {HMP_APPLY}; run validate_integrated_candidate_surface_hmp_abundance_policy.py"
        )
    apply = pd.read_csv(HMP_APPLY, sep="\t")
    paths: dict[tuple[str, int], Path] = {}
    missing_rows = []
    for row in apply.itertuples(index=False):
        if str(getattr(row, "status", "")) != "replayed":
            continue
        panel = str(row.panel)
        sample = int(row.sample)
        path = Path(str(row.out))
        if path.exists():
            paths[(panel, sample)] = path
        else:
            missing_rows.append({"panel": panel, "sample": sample, "profile": str(path)})
    return paths, pd.DataFrame(missing_rows)


def candidate_metadata(path_map: dict[tuple[str, int], Path]) -> pd.DataFrame:
    rows = []
    for (panel, sample), path in path_map.items():
        df = pd.read_csv(
            path,
            sep="\t",
            usecols=lambda col: col
            in {
                "calibrated_call",
                "calibrated_abundance",
                "calibrated_abundance_raw",
                "candidate_rescue_added",
                "candidate_surface_added",
                "candidate_abundance_policy",
                "candidate_abundance_norm_mass",
            },
            low_memory=False,
        )
        called = bool_series(df.get("calibrated_call", pd.Series(False, index=df.index)))
        rescue_added = bool_series(df.get("candidate_rescue_added", pd.Series(False, index=df.index)))
        surface_added = bool_series(df.get("candidate_surface_added", pd.Series(False, index=df.index)))
        added = rescue_added | surface_added
        raw = pd.to_numeric(df.get("calibrated_abundance_raw", 0.0), errors="coerce").fillna(0.0)
        abundance = pd.to_numeric(df.get("calibrated_abundance", 0.0), errors="coerce").fillna(0.0)
        norm_mass = pd.to_numeric(
            df.get("candidate_abundance_norm_mass", 0.0),
            errors="coerce",
        ).fillna(0.0)
        base_called_raw_mass = float(raw.loc[called & ~added].sum())
        if base_called_raw_mass <= 0.0:
            base_called_raw_mass = 1.0
        expected_raw = norm_mass * base_called_raw_mass
        raw_delta = (raw - expected_raw).abs()
        policy_values = (
            ",".join(sorted(set(df.loc[added, "candidate_abundance_policy"].astype(str))))
            if "candidate_abundance_policy" in df.columns and added.any()
            else ""
        )
        rows.append(
            {
                "panel": panel,
                "sample": str(sample),
                "profile": str(path),
                "called_rows": int(called.sum()),
                "candidate_added_rows": int(added.sum()),
                "candidate_rescue_added_rows": int(rescue_added.sum()),
                "candidate_surface_added_rows": int(surface_added.sum()),
                "nonzero_candidate_rows": int((raw.loc[added] > 0.0).sum()),
                "candidate_added_abundance_sum": float(abundance.loc[added].sum()),
                "candidate_added_raw_sum": float(raw.loc[added].sum()),
                "candidate_added_norm_mass_sum": float(norm_mass.loc[added].sum()),
                "base_called_raw_mass": base_called_raw_mass,
                "max_candidate_raw_mass_delta": float(raw_delta.loc[added].max()) if added.any() else 0.0,
                "candidate_abundance_policy_values": policy_values,
            }
        )
    return pd.DataFrame(rows)


def summarize(scores: pd.DataFrame) -> pd.DataFrame:
    rows = []
    for panel, sub in scores.groupby("panel", sort=True):
        tp = int(sub["TP"].sum())
        fp = int(sub["FP"].sum())
        fn = int(sub["FN"].sum())
        precision = tp / (tp + fp) if tp + fp else 0.0
        recall = tp / (tp + fn) if tp + fn else 0.0
        pooled_f1 = 2.0 * precision * recall / (precision + recall) if precision + recall else 0.0
        l1_col = adaptive.official_l1_col(panel)
        pearson_col = adaptive.official_pearson_col(panel)
        rows.append(
            {
                "panel": panel,
                "method": METHOD,
                "samples": ",".join(map(str, sorted(sub["sample"].astype(int).unique()))),
                "sample_count": int(len(sub)),
                "mean_F1": sub["F1"].mean(),
                "pooled_F1": pooled_f1,
                "pooled_TP": tp,
                "pooled_FP": fp,
                "pooled_FN": fn,
                "official_L1_pp": sub[l1_col].mean(),
                "official_Pearson": sub[pearson_col].mean(),
                "candidate_added_rows": int(sub["candidate_added_rows"].sum()),
                "nonzero_candidate_rows": int(sub["nonzero_candidate_rows"].sum()),
                "candidate_added_abundance_sum": sub["candidate_added_abundance_sum"].sum(),
                "candidate_added_norm_mass_sum": sub["candidate_added_norm_mass_sum"].sum(),
            }
        )
    return pd.DataFrame(rows)


def make_zero_mass_profiles(path_map: dict[tuple[str, int], Path]) -> dict[tuple[str, int], Path]:
    zero_dir = OUT_DIR / "zero_mass_profiles"
    zero_dir.mkdir(parents=True, exist_ok=True)
    out_paths: dict[tuple[str, int], Path] = {}
    for key, path in path_map.items():
        panel, sample = key
        out = zero_dir / f"{panel}.sample{sample}.zero_mass.tsv"
        df = pd.read_csv(path, sep="\t", low_memory=False)
        called = bool_series(df.get("calibrated_call", pd.Series(False, index=df.index)))
        rescue_added = bool_series(df.get("candidate_rescue_added", pd.Series(False, index=df.index)))
        surface_added = bool_series(df.get("candidate_surface_added", pd.Series(False, index=df.index)))
        added = rescue_added | surface_added
        raw = pd.to_numeric(df.get("calibrated_abundance_raw", 0.0), errors="coerce").fillna(0.0)
        raw.loc[added] = 0.0
        raw = raw.clip(lower=0.0)
        df["calibrated_abundance_raw"] = raw
        called_mass = float(raw.loc[called].sum())
        if called_mass > 0.0:
            df["calibrated_abundance"] = 0.0
            df.loc[called, "calibrated_abundance"] = raw.loc[called] / called_mass
        else:
            df["calibrated_abundance"] = 0.0
        df.to_csv(out, sep="\t", index=False)
        out_paths[key] = out
    return out_paths


def score_wrapper_profiles(
    emitted_paths: dict[tuple[str, int], Path],
    hmp_profile_paths: dict[tuple[str, int], Path],
    method: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    adaptive.METHOD = method
    emitted_scores, emitted_meta = adaptive.score_profiles(emitted_paths)
    mapper = raw_audit.RawMapper()
    hmp_rows = []
    for (panel, sample), path in hmp_profile_paths.items():
        row = hmp_abundance.score_profile(panel, int(sample), path, mapper)
        row["method"] = method
        row["panel"] = panel
        row["sample"] = str(sample)
        row["profile"] = str(path)
        hmp_rows.append(row)
    hmp_scores = pd.DataFrame(hmp_rows)
    scores = pd.concat([emitted_scores, hmp_scores], ignore_index=True, sort=False)
    return scores, emitted_meta


def compare_to_zero(scores: pd.DataFrame, zero_scores: pd.DataFrame) -> pd.DataFrame:
    zero = {
        (str(row.panel), int(row.sample)): row
        for row in zero_scores.itertuples(index=False)
    }
    rows = []
    for row in scores.itertuples(index=False):
        panel = str(row.panel)
        sample = int(row.sample)
        base = zero[(panel, sample)]
        l1_col = adaptive.official_l1_col(panel)
        pearson_col = adaptive.official_pearson_col(panel)
        rows.append(
            {
                "panel": panel,
                "sample": sample,
                "F1_delta_vs_zero": finite(row.F1) - finite(base.F1),
                "official_L1_delta_vs_zero_pp": finite(getattr(row, l1_col)) - finite(getattr(base, l1_col)),
                "official_Pearson_delta_vs_zero": finite(getattr(row, pearson_col)) - finite(getattr(base, pearson_col)),
            }
        )
    return pd.DataFrame(rows)


def compare_to_expected(scores: pd.DataFrame) -> pd.DataFrame:
    if not EXPECTED.exists():
        raise SystemExit(f"missing expected fixed-call scores: {EXPECTED}")
    expected = pd.read_csv(EXPECTED, sep="\t")
    rows = []
    for row in scores.itertuples(index=False):
        panel = str(row.panel)
        sample = int(row.sample)
        exp = expected.loc[
            expected["panel"].astype(str).eq(panel)
            & expected["sample"].astype(int).eq(sample)
            & expected["method"].astype(str).eq(EXPECTED_METHOD)
        ]
        if exp.empty:
            rows.append(
                {"panel": panel, "sample": sample, "status": "missing_expected", "path": str(EXPECTED)}
            )
            continue
        exp_row = exp.iloc[0]
        l1_col = adaptive.official_l1_col(panel)
        pearson_col = adaptive.official_pearson_col(panel)
        expected_l1 = "official_L1_pp"
        expected_pearson = pearson_col
        rows.append(
            {
                "panel": panel,
                "sample": sample,
                "status": "compared",
                "TP_delta": int(row.TP) - int(exp_row["TP"]),
                "FP_delta": int(row.FP) - int(exp_row["FP"]),
                "FN_delta": int(row.FN) - int(exp_row["FN"]),
                "F1_delta": finite(row.F1) - finite(exp_row["F1"]),
                "official_L1_delta_pp": finite(getattr(row, l1_col)) - finite(exp_row[expected_l1]),
                "official_Pearson_delta": finite(getattr(row, pearson_col)) - finite(exp_row[expected_pearson]),
            }
        )
    return pd.DataFrame(rows)


def audit(
    scores: pd.DataFrame,
    meta: pd.DataFrame,
    comparison: pd.DataFrame,
    zero_comparison: pd.DataFrame,
) -> pd.DataFrame:
    compared = comparison.loc[comparison["status"].astype(str).eq("compared")].copy()
    if compared.empty:
        comparison_value = "missing"
        comparison_decision = "missing_comparison"
    else:
        max_count_delta = int(compared[["TP_delta", "FP_delta", "FN_delta"]].abs().max().max())
        max_f1_delta = float(compared["F1_delta"].abs().max())
        max_l1_delta = float(compared["official_L1_delta_pp"].abs().max())
        max_pearson_delta = float(compared["official_Pearson_delta"].abs().max())
        comparison_value = (
            f"counts={max_count_delta};F1={max_f1_delta:.3g};"
            f"L1={max_l1_delta:.3g};Pearson={max_pearson_delta:.3g}"
        )
        comparison_decision = (
            "call_set_matches_abundance_differs"
            if max_count_delta == 0 and max_f1_delta < 1e-9
            else "differs"
        )
    if zero_comparison.empty:
        zero_value = "missing"
        zero_decision = "missing_zero_baseline"
    else:
        zero_value = (
            f"mean_L1={zero_comparison['official_L1_delta_vs_zero_pp'].mean():.6f};"
            f"max_worse_L1={zero_comparison['official_L1_delta_vs_zero_pp'].max():.6f};"
            f"mean_Pearson={zero_comparison['official_Pearson_delta_vs_zero'].mean():.6f};"
            f"worsened_samples={int((zero_comparison['official_L1_delta_vs_zero_pp'] > 1e-12).sum())}"
        )
        zero_decision = (
            "sample_safe_abundance_improvement"
            if int((zero_comparison["official_L1_delta_vs_zero_pp"] > 1e-12).sum()) == 0
            else "has_sample_regressions"
        )
    max_raw_delta = float(meta["max_candidate_raw_mass_delta"].max()) if not meta.empty else 0.0
    rows = [
        {
            "metric": "wrapper_profiles_scored",
            "value": int(scores.shape[0]),
            "evidence": str(OUT_DIR),
            "decision": "cross_panel_cached_wrapper_replay",
        },
        {
            "metric": "candidate_added_rows",
            "value": int(meta["candidate_added_rows"].sum()) if not meta.empty else 0,
            "evidence": "candidate_rescue_added or candidate_surface_added",
            "decision": "candidate_behavior",
        },
        {
            "metric": "nonzero_candidate_rows",
            "value": int(meta["nonzero_candidate_rows"].sum()) if not meta.empty else 0,
            "evidence": POLICY,
            "decision": "candidate_abundance_behavior",
        },
        {
            "metric": "max_candidate_raw_mass_delta",
            "value": max_raw_delta,
            "evidence": "calibrated_abundance_raw versus candidate_abundance_norm_mass*base_called_raw_mass",
            "decision": "pass" if max_raw_delta < 1e-9 else "fail",
        },
        {
            "metric": "max_delta_vs_fixed_call_policy_sweep",
            "value": comparison_value,
            "evidence": "cross_panel_candidate_abundance_wrapper_vs_policy_sweep.tsv",
            "decision": comparison_decision,
        },
        {
            "metric": "delta_vs_wrapper_zero_mass",
            "value": zero_value,
            "evidence": "cross_panel_candidate_abundance_wrapper_vs_zero.tsv",
            "decision": zero_decision,
        },
        {
            "metric": "promotion_decision",
            "value": "experimental_not_default",
            "evidence": "wrapper replay call set matches fixed-call policy; abundance must be judged against matched wrapper zero-mass baseline",
            "decision": "do_not_change_current_default",
        },
    ]
    return pd.DataFrame(rows)


def main() -> int:
    RESULTS.mkdir(parents=True, exist_ok=True)
    emitted_paths, emitted_timing, emitted_missing = replay_emitted_profiles()
    hmp_profile_paths, hmp_missing = hmp_paths()
    path_map = {**emitted_paths, **hmp_profile_paths}
    if emitted_missing.empty and hmp_missing.empty:
        missing = pd.DataFrame()
    else:
        missing = pd.concat([emitted_missing, hmp_missing], ignore_index=True, sort=False)
    if missing.empty and len(path_map) != 32:
        missing = pd.DataFrame([{"panel": "", "sample": "", "profile": "", "reason": f"expected 32 profiles, found {len(path_map)}"}])
    if not missing.empty:
        missing.to_csv(RESULTS / "cross_panel_candidate_abundance_wrapper_missing.tsv", sep="\t", index=False)
        raise SystemExit("missing cross-panel wrapper inputs; see cross_panel_candidate_abundance_wrapper_missing.tsv")

    scores, scorer_meta = score_wrapper_profiles(emitted_paths, hmp_profile_paths, METHOD)
    zero_paths = make_zero_mass_profiles(path_map)
    zero_emitted = {key: path for key, path in zero_paths.items() if key in emitted_paths}
    zero_hmp = {key: path for key, path in zero_paths.items() if key in hmp_profile_paths}
    zero_scores, _zero_scorer_meta = score_wrapper_profiles(zero_emitted, zero_hmp, ZERO_METHOD)
    meta = candidate_metadata(path_map)
    scores = scores.merge(meta.drop(columns=["profile"]), on=["panel", "sample"], how="left")
    summary = summarize(scores)
    comparison = compare_to_expected(scores)
    zero_comparison = compare_to_zero(scores, zero_scores)
    audit_df = audit(scores, meta, comparison, zero_comparison)

    pd.DataFrame(
        [
            {
                "source": "emitted_wrapper_replay",
                "profiles": len(emitted_paths),
                "path": str(OUT_DIR),
            },
            {
                "source": "hmp_candidate_surface_replay",
                "profiles": len(hmp_profile_paths),
                "path": str(HMP_APPLY),
            },
        ]
    ).to_csv(RESULTS / "cross_panel_candidate_abundance_wrapper_apply.tsv", sep="\t", index=False)
    emitted_timing.to_csv(RESULTS / "cross_panel_candidate_abundance_wrapper_runtime.tsv", sep="\t", index=False)
    scorer_meta.to_csv(RESULTS / "cross_panel_candidate_abundance_wrapper_scorer_metadata.tsv", sep="\t", index=False)
    meta.to_csv(RESULTS / "cross_panel_candidate_abundance_wrapper_candidate_metadata.tsv", sep="\t", index=False)
    zero_scores.to_csv(RESULTS / "cross_panel_candidate_abundance_wrapper_zero_scores.tsv", sep="\t", index=False)
    scores.to_csv(RESULTS / "cross_panel_candidate_abundance_wrapper_scores.tsv", sep="\t", index=False)
    summary.to_csv(RESULTS / "cross_panel_candidate_abundance_wrapper_summary.tsv", sep="\t", index=False)
    comparison.to_csv(RESULTS / "cross_panel_candidate_abundance_wrapper_vs_policy_sweep.tsv", sep="\t", index=False)
    zero_comparison.to_csv(RESULTS / "cross_panel_candidate_abundance_wrapper_vs_zero.tsv", sep="\t", index=False)
    audit_df.to_csv(RESULTS / "cross_panel_candidate_abundance_wrapper_audit.tsv", sep="\t", index=False)

    print(summary.to_string(index=False))
    print("\nAUDIT")
    print(audit_df.to_string(index=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
